#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>

std::vector<int> minMaxSum(const std::vector<int>& nums) {
    int smallest = *std::min_element(nums.begin(), nums.end());
    int largest = *std::max_element(nums.begin(), nums.end());
    int total = std::accumulate(nums.begin(), nums.end(), 0);
    return {smallest, largest, total};
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int& x : nums) {
        std::cin >> x;
    }
    std::vector<int> result = minMaxSum(nums);
    std::cout << result[0] << " " << result[1] << " " << result[2] << "\n";
    return 0;
}

