package main

import "fmt"

func minMaxSum(nums []int) []int {
	// Go 1.16 has no built-in min or max for ints, so one loop finds all three.
	smallest, largest, total := nums[0], nums[0], 0
	for _, x := range nums {
		if x < smallest {
			smallest = x
		}
		if x > largest {
			largest = x
		}
		total += x
	}
	return []int{smallest, largest, total}
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	result := minMaxSum(nums)
	fmt.Println(result[0], result[1], result[2])
}
